 static void ReceiptCheckpointPressure(){var ports=new ReceiptPorts();var health=new HealthService("pressure",0,0,true,ports,ports,ports,60,5,0);Need(health.RegisterConfiguredSpawn(new CommandContext("pressure","host","spawn",1,0,true),"p",-1,false,100,0).Accepted,"Pressure source spawn");string first=new string('r',120)+"0";int checkpoints=0,refused=0;
  for(int i=0;i<10000;i++){var c=new CommandContext("pressure","host","damage-"+i,i+2,0,true);string logical=new string('r',120)+i;Need(health.ApplyDamage(c,logical,"p",health.Read("p").Revision,.0001f,0,false).Result.Accepted,"Long logical receipt "+i);health.DrainTransitions();if(i==999||i==4095||i==8191||i==9999){try{var image=health.CreateCheckpoint(new CommandContext("pressure","host","checkpoint-"+i,i+2,0,true),new string('b',64));Console.WriteLine("RECEIPT PRESSURE count="+(i+1)+" checkpointBytes="+image.Length+" limit=2097152");checkpoints++;}catch(InvalidOperationException e){Need(e.Message=="checkpoint-size","Explicit size refusal only");Console.WriteLine("RECEIPT PRESSURE count="+(i+1)+" refused="+e.Message+" limit=2097152");refused++;}}}
  Need(checkpoints>0&&refused>0,"Measured exact receipt serialization crosses its unchanged checkpoint bound");float hp=health.Read("p").Health;Need(health.ApplyDamage(new CommandContext("pressure","host","fresh-retry",10003,0,true),first,"p",health.Read("p").Revision,50,0,false).Result.Accepted&&health.Read("p").Health==hp,"A fresh command cannot reapply an old logical hit after checkpoint refusal");Need(health.ApplyDamage(new CommandContext("pressure","host","after-failure",10004,0,true),"after-failure","p",health.Read("p").Revision,.0001f,0,false).Result.Accepted,"Checkpoint refusal never silently disables normal damage");
 }
